<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_admin_safety() { if ( ! current_user_can( 'sd_manage_safety_settings' ) ) { wp_die( esc_html__( 'You are not allowed to view this page.', 'social-discovery-core' ) ); } if ( isset( $_POST['sd_safety_save'] ) ) { check_admin_referer( 'sd_safety_settings' ); update_option( 'sd_safety_reporting_enabled', ! empty( $_POST['reporting_enabled'] ) ); update_option( 'sd_safety_blocking_enabled', ! empty( $_POST['blocking_enabled'] ) ); } ?><div class="wrap"><h1><?php esc_html_e( 'Safety Settings', 'social-discovery-core' ); ?></h1><form method="post"><?php wp_nonce_field( 'sd_safety_settings' ); ?><p><label><input type="checkbox" name="reporting_enabled" value="1" <?php checked( get_option( 'sd_safety_reporting_enabled', true ) ); ?>> <?php esc_html_e( 'Enable reporting', 'social-discovery-core' ); ?></label></p><p><label><input type="checkbox" name="blocking_enabled" value="1" <?php checked( get_option( 'sd_safety_blocking_enabled', true ) ); ?>> <?php esc_html_e( 'Enable member blocking', 'social-discovery-core' ); ?></label></p><p><button class="button button-primary" name="sd_safety_save" value="1"><?php esc_html_e( 'Save settings', 'social-discovery-core' ); ?></button></p></form></div><?php }
